package mx.escuelaministerio.app;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/** Database facade for travel registration, buses, passengers and seats. */
final class TransportProgram {
    static final String STUDENT="STUDENT",INTERESTED="INTERESTED";
    static final class Trip {
        long id;String date="",time="",reason="",departurePlace="",congregation="",locality="";boolean registrationClosed,finalized;
        @Override public String toString(){return date+" · "+time+" · "+reason;}
    }
    static final class Bus {
        long id,tripId,captainPassengerId,assistantPassengerId;int number,capacity;
        @Override public String toString(){return "Autobús "+number+" · "+capacity+" asientos";}
    }
    static final class InterestedPerson {
        long id;String name="";
        @Override public String toString(){return name;}
    }
    static final class Passenger {
        long id,tripId,sourceId,busId;String sourceKind="",name="";int seatNumber;
        boolean hasSeat(){return busId!=0&&seatNumber>0;}
        @Override public String toString(){return name+(hasSeat()?" · Asiento "+seatNumber:"");}
    }
    static final class PersonChoice {
        final String kind;final long sourceId;final String name;
        PersonChoice(String kind,long sourceId,String name){this.kind=kind;this.sourceId=sourceId;this.name=name;}
        @Override public String toString(){return name+(STUDENT.equals(kind)?" · Alumno":" · Persona interesada");}
    }
    static final class PassengerTrip {
        String date="",time="",reason="",departurePlace="";int bus,seat;boolean captain,assistant;
    }
    private final MinisterioDb db;
    TransportProgram(MinisterioDb db){this.db=db;}

    static void validateTrip(Trip trip){
        try{LocalDate.parse(trip.date);}catch(Exception error){throw new IllegalArgumentException("Seleccione una fecha de viaje válida.");}
        try{LocalTime.parse(trip.time);}catch(Exception error){throw new IllegalArgumentException("Seleccione una hora de salida válida.");}
        if(trip.reason.trim().isEmpty())throw new IllegalArgumentException("Indique el motivo del viaje.");
        if(trip.departurePlace.trim().isEmpty())throw new IllegalArgumentException("Indique el lugar de salida.");
    }
    List<Trip> trips(){List<Trip> result=new ArrayList<>();try(Cursor r=db.getReadableDatabase().rawQuery("SELECT id,travel_date,departure_time,reason,departure_place,congregation,locality,registration_closed,finalized FROM transport_trips ORDER BY travel_date DESC,departure_time DESC,id DESC",null)){while(r.moveToNext()){Trip t=new Trip();t.id=r.getLong(0);t.date=r.getString(1);t.time=r.getString(2);t.reason=r.getString(3);t.departurePlace=r.getString(4);t.congregation=r.getString(5);t.locality=r.getString(6);t.registrationClosed=r.getInt(7)!=0;t.finalized=r.getInt(8)!=0;result.add(t);}}return result;}
    Trip trip(long id){for(Trip trip:trips())if(trip.id==id)return trip;throw new IllegalArgumentException("El viaje ya no existe.");}
    long createTrip(Trip trip,int[] capacities){validateTrip(trip);if(capacities==null||capacities.length==0||capacities.length>20)throw new IllegalArgumentException("Defina entre uno y veinte autobuses.");for(int capacity:capacities)if(capacity<1||capacity>100)throw new IllegalArgumentException("La capacidad de cada autobús debe estar entre 1 y 100.");
        SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{ContentValues value=tripValues(trip);long id=sql.insertOrThrow("transport_trips",null,value);for(int i=0;i<capacities.length;i++){ContentValues bus=new ContentValues();bus.put("trip_id",id);bus.put("bus_number",i+1);bus.put("capacity",capacities[i]);sql.insertOrThrow("transport_buses",null,bus);}sql.setTransactionSuccessful();trip.id=id;return id;}finally{sql.endTransaction();}}
    void replaceBuses(Trip trip,int[] capacities){if(trip.finalized||passengerCount(trip.id)>0)throw new IllegalArgumentException("Los autobuses solo pueden cambiarse antes de registrar pasajeros.");if(capacities==null||capacities.length==0||capacities.length>20)throw new IllegalArgumentException("Defina entre uno y veinte autobuses.");for(int capacity:capacities)if(capacity<1||capacity>100)throw new IllegalArgumentException("La capacidad debe estar entre 1 y 100.");SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{sql.delete("transport_buses","trip_id=?",new String[]{String.valueOf(trip.id)});for(int i=0;i<capacities.length;i++){ContentValues bus=new ContentValues();bus.put("trip_id",trip.id);bus.put("bus_number",i+1);bus.put("capacity",capacities[i]);sql.insertOrThrow("transport_buses",null,bus);}sql.setTransactionSuccessful();}finally{sql.endTransaction();}}
    void updateTrip(Trip trip){validateTrip(trip);db.getWritableDatabase().update("transport_trips",tripValues(trip),"id=?",new String[]{String.valueOf(trip.id)});}
    private static ContentValues tripValues(Trip trip){ContentValues value=new ContentValues();value.put("travel_date",trip.date);value.put("departure_time",trip.time);value.put("reason",trip.reason.trim());value.put("departure_place",trip.departurePlace.trim());value.put("congregation",trip.congregation==null?"":trip.congregation.trim());value.put("locality",trip.locality==null?"":trip.locality.trim());value.put("registration_closed",trip.registrationClosed?1:0);value.put("finalized",trip.finalized?1:0);return value;}
    void deleteTrip(long id){SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{for(Bus bus:buses(id))sql.delete("transport_seats","bus_id=?",new String[]{String.valueOf(bus.id)});sql.delete("transport_passengers","trip_id=?",new String[]{String.valueOf(id)});sql.delete("transport_buses","trip_id=?",new String[]{String.valueOf(id)});sql.delete("transport_trips","id=?",new String[]{String.valueOf(id)});sql.setTransactionSuccessful();}finally{sql.endTransaction();}}
    List<Bus> buses(long tripId){List<Bus> result=new ArrayList<>();try(Cursor r=db.getReadableDatabase().rawQuery("SELECT id,trip_id,bus_number,capacity,captain_passenger_id,assistant_passenger_id FROM transport_buses WHERE trip_id=? ORDER BY bus_number",new String[]{String.valueOf(tripId)})){while(r.moveToNext()){Bus b=new Bus();b.id=r.getLong(0);b.tripId=r.getLong(1);b.number=r.getInt(2);b.capacity=r.getInt(3);b.captainPassengerId=r.getLong(4);b.assistantPassengerId=r.getLong(5);result.add(b);}}return result;}
    Bus bus(long busId){try(Cursor r=db.getReadableDatabase().rawQuery("SELECT id,trip_id,bus_number,capacity,captain_passenger_id,assistant_passenger_id FROM transport_buses WHERE id=?",new String[]{String.valueOf(busId)})){if(r.moveToFirst()){Bus b=new Bus();b.id=r.getLong(0);b.tripId=r.getLong(1);b.number=r.getInt(2);b.capacity=r.getInt(3);b.captainPassengerId=r.getLong(4);b.assistantPassengerId=r.getLong(5);return b;}}throw new IllegalArgumentException("El autobús ya no existe.");}
    int totalCapacity(long tripId){int result=0;for(Bus bus:buses(tripId))result+=bus.capacity;return result;}
    int passengerCount(long tripId){try(Cursor r=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM transport_passengers WHERE trip_id=?",new String[]{String.valueOf(tripId)})){return r.moveToFirst()?r.getInt(0):0;}}
    int seatedCount(long tripId){try(Cursor r=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM transport_seats s JOIN transport_buses b ON b.id=s.bus_id WHERE b.trip_id=?",new String[]{String.valueOf(tripId)})){return r.moveToFirst()?r.getInt(0):0;}}
    boolean canAssignSeats(Trip trip){return trip.registrationClosed||passengerCount(trip.id)>=totalCapacity(trip.id);}
    void closeRegistration(Trip trip){ContentValues value=new ContentValues();value.put("registration_closed",1);db.getWritableDatabase().update("transport_trips",value,"id=?",new String[]{String.valueOf(trip.id)});trip.registrationClosed=true;}
    void reopenRegistration(Trip trip){if(trip.finalized)throw new IllegalArgumentException("El programa final ya no puede reabrirse.");ContentValues value=new ContentValues();value.put("registration_closed",0);db.getWritableDatabase().update("transport_trips",value,"id=?",new String[]{String.valueOf(trip.id)});trip.registrationClosed=false;}

    List<InterestedPerson> interestedPeople(){List<InterestedPerson> result=new ArrayList<>();try(Cursor r=db.getReadableDatabase().rawQuery("SELECT id,name FROM transport_interested_people ORDER BY name COLLATE NOCASE,id",null)){while(r.moveToNext()){InterestedPerson p=new InterestedPerson();p.id=r.getLong(0);p.name=r.getString(1);result.add(p);}}return result;}
    InterestedPerson addInterestedPerson(String name){String clean=name==null?"":name.trim();if(clean.isEmpty())throw new IllegalArgumentException("Escriba el nombre de la persona interesada.");InterestedPerson person=new InterestedPerson();person.name=clean;ContentValues value=new ContentValues();value.put("name",clean);person.id=db.getWritableDatabase().insertOrThrow("transport_interested_people",null,value);return person;}
    void renameInterestedPerson(InterestedPerson person,String name){String clean=name==null?"":name.trim();if(clean.isEmpty())throw new IllegalArgumentException("Escriba el nombre.");ContentValues value=new ContentValues();value.put("name",clean);db.getWritableDatabase().update("transport_interested_people",value,"id=?",new String[]{String.valueOf(person.id)});person.name=clean;}
    void deleteInterestedPerson(InterestedPerson person){try(Cursor r=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM transport_passengers WHERE source_kind='INTERESTED' AND source_id=?",new String[]{String.valueOf(person.id)})){if(r.moveToFirst()&&r.getInt(0)>0)throw new IllegalArgumentException("No puede eliminarse porque forma parte del histórico de viajes.");}db.getWritableDatabase().delete("transport_interested_people","id=?",new String[]{String.valueOf(person.id)});}
    List<PersonChoice> availablePeople(long tripId){List<PersonChoice> result=new ArrayList<>();for(Models.Student s:db.students(false))if(!registered(tripId,STUDENT,s.id))result.add(new PersonChoice(STUDENT,s.id,s.name));for(InterestedPerson p:interestedPeople())if(!registered(tripId,INTERESTED,p.id))result.add(new PersonChoice(INTERESTED,p.id,p.name));return result;}
    private boolean registered(long tripId,String kind,long sourceId){try(Cursor r=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM transport_passengers WHERE trip_id=? AND source_kind=? AND source_id=?",new String[]{String.valueOf(tripId),kind,String.valueOf(sourceId)})){return r.moveToFirst()&&r.getInt(0)>0;}}
    long registerPassenger(Trip trip,PersonChoice person){if(trip.registrationClosed||passengerCount(trip.id)>=totalCapacity(trip.id))throw new IllegalArgumentException("El registro de pasajeros está cerrado o no quedan espacios disponibles.");ContentValues value=new ContentValues();value.put("trip_id",trip.id);value.put("source_kind",person.kind);value.put("source_id",person.sourceId);value.put("passenger_name",person.name);long id=db.getWritableDatabase().insertOrThrow("transport_passengers",null,value);if(passengerCount(trip.id)>=totalCapacity(trip.id))closeRegistration(trip);return id;}
    void removePassenger(Trip trip,long passengerId){if(trip.finalized)throw new IllegalArgumentException("No se puede retirar un pasajero de un programa finalizado.");SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{sql.delete("transport_seats","passenger_id=?",new String[]{String.valueOf(passengerId)});clearResponsibility(sql,trip.id,passengerId);sql.delete("transport_passengers","id=? AND trip_id=?",new String[]{String.valueOf(passengerId),String.valueOf(trip.id)});ContentValues draft=new ContentValues();draft.put("finalized",0);sql.update("transport_trips",draft,"id=?",new String[]{String.valueOf(trip.id)});sql.setTransactionSuccessful();trip.finalized=false;}finally{sql.endTransaction();}}
    List<Passenger> passengers(long tripId){List<Passenger> result=new ArrayList<>();String sql="SELECT p.id,p.trip_id,p.source_kind,p.source_id,p.passenger_name,COALESCE(s.bus_id,0),COALESCE(s.seat_number,0) FROM transport_passengers p LEFT JOIN transport_seats s ON s.passenger_id=p.id WHERE p.trip_id=? ORDER BY p.passenger_name COLLATE NOCASE,p.id";try(Cursor r=db.getReadableDatabase().rawQuery(sql,new String[]{String.valueOf(tripId)})){while(r.moveToNext()){Passenger p=new Passenger();p.id=r.getLong(0);p.tripId=r.getLong(1);p.sourceKind=r.getString(2);p.sourceId=r.getLong(3);p.name=r.getString(4);p.busId=r.getLong(5);p.seatNumber=r.getInt(6);result.add(p);}}return result;}
    Passenger passenger(long id){try(Cursor r=db.getReadableDatabase().rawQuery("SELECT p.id,p.trip_id,p.source_kind,p.source_id,p.passenger_name,COALESCE(s.bus_id,0),COALESCE(s.seat_number,0) FROM transport_passengers p LEFT JOIN transport_seats s ON s.passenger_id=p.id WHERE p.id=?",new String[]{String.valueOf(id)})){if(r.moveToFirst()){Passenger p=new Passenger();p.id=r.getLong(0);p.tripId=r.getLong(1);p.sourceKind=r.getString(2);p.sourceId=r.getLong(3);p.name=r.getString(4);p.busId=r.getLong(5);p.seatNumber=r.getInt(6);return p;}}throw new IllegalArgumentException("El pasajero ya no existe.");}
    List<Passenger> passengersOnBus(long busId){List<Passenger> result=new ArrayList<>();for(Passenger passenger:passengers(bus(busId).tripId))if(passenger.busId==busId)result.add(passenger);result.sort((a,b)->Integer.compare(a.seatNumber,b.seatNumber));return result;}
    Passenger passengerAt(long busId,int seat){try(Cursor r=db.getReadableDatabase().rawQuery("SELECT passenger_id FROM transport_seats WHERE bus_id=? AND seat_number=?",new String[]{String.valueOf(busId),String.valueOf(seat)})){return r.moveToFirst()?passenger(r.getLong(0)):null;}}
    void assignSeat(Trip trip,Bus bus,int seat,long passengerId){if(!canAssignSeats(trip))throw new IllegalArgumentException("Cierre primero el registro de pasajeros.");if(trip.finalized)throw new IllegalArgumentException("El programa está finalizado. Reabra la edición antes de cambiar asientos.");if(seat<1||seat>bus.capacity)throw new IllegalArgumentException("El asiento está fuera de la capacidad del autobús.");Passenger passenger=passenger(passengerId);if(passenger.tripId!=trip.id)throw new IllegalArgumentException("El pasajero pertenece a otro viaje.");Passenger displaced=passengerAt(bus.id,seat);SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{clearResponsibility(sql,trip.id,passengerId);if(displaced!=null&&displaced.id!=passengerId)clearResponsibility(sql,trip.id,displaced.id);sql.delete("transport_seats","passenger_id=? OR (bus_id=? AND seat_number=?)",new String[]{String.valueOf(passengerId),String.valueOf(bus.id),String.valueOf(seat)});ContentValues value=new ContentValues();value.put("bus_id",bus.id);value.put("seat_number",seat);value.put("passenger_id",passengerId);sql.insertOrThrow("transport_seats",null,value);sql.setTransactionSuccessful();}finally{sql.endTransaction();}}
    void clearSeat(Trip trip,long passengerId){if(trip.finalized)throw new IllegalArgumentException("El programa está finalizado.");SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{clearResponsibility(sql,trip.id,passengerId);sql.delete("transport_seats","passenger_id=?",new String[]{String.valueOf(passengerId)});sql.setTransactionSuccessful();}finally{sql.endTransaction();}}
    private static void clearResponsibility(SQLiteDatabase sql,long tripId,long passengerId){ContentValues captain=new ContentValues();captain.put("captain_passenger_id",0);sql.update("transport_buses",captain,"trip_id=? AND captain_passenger_id=?",new String[]{String.valueOf(tripId),String.valueOf(passengerId)});ContentValues assistant=new ContentValues();assistant.put("assistant_passenger_id",0);sql.update("transport_buses",assistant,"trip_id=? AND assistant_passenger_id=?",new String[]{String.valueOf(tripId),String.valueOf(passengerId)});}
    void setCaptain(Trip trip,Bus bus,long passengerId){if(trip.finalized)throw new IllegalArgumentException("El programa está finalizado.");Passenger passenger=passenger(passengerId);if(passenger.tripId!=trip.id||passenger.busId!=bus.id)throw new IllegalArgumentException("El capitán debe ser un pasajero con asiento en este autobús.");if(passengerId==bus.assistantPassengerId)throw new IllegalArgumentException("El capitán y el auxiliar deben ser pasajeros distintos.");ContentValues value=new ContentValues();value.put("captain_passenger_id",passengerId);db.getWritableDatabase().update("transport_buses",value,"id=?",new String[]{String.valueOf(bus.id)});bus.captainPassengerId=passengerId;}
    void setAssistant(Trip trip,Bus bus,long passengerId){if(trip.finalized)throw new IllegalArgumentException("El programa está finalizado.");Passenger passenger=passenger(passengerId);if(passenger.tripId!=trip.id||passenger.busId!=bus.id)throw new IllegalArgumentException("El auxiliar debe ser un pasajero con asiento en este autobús.");if(passengerId==bus.captainPassengerId)throw new IllegalArgumentException("El capitán y el auxiliar deben ser pasajeros distintos.");ContentValues value=new ContentValues();value.put("assistant_passenger_id",passengerId);db.getWritableDatabase().update("transport_buses",value,"id=?",new String[]{String.valueOf(bus.id)});bus.assistantPassengerId=passengerId;}
    void finalizeProgram(Trip trip){if(!canAssignSeats(trip))throw new IllegalArgumentException("Cierre primero el registro.");if(seatedCount(trip.id)!=passengerCount(trip.id))throw new IllegalArgumentException("Todos los pasajeros deben tener asiento antes de finalizar.");for(Bus bus:buses(trip.id)){if(bus.captainPassengerId==0)throw new IllegalArgumentException("Asigne un capitán al autobús "+bus.number+".");if(bus.assistantPassengerId==0)throw new IllegalArgumentException("Asigne un auxiliar al autobús "+bus.number+".");if(bus.captainPassengerId==bus.assistantPassengerId)throw new IllegalArgumentException("El capitán y el auxiliar del autobús "+bus.number+" deben ser distintos.");Passenger captain=passenger(bus.captainPassengerId),assistant=passenger(bus.assistantPassengerId);if(captain.busId!=bus.id||assistant.busId!=bus.id)throw new IllegalArgumentException("El capitán y el auxiliar del autobús "+bus.number+" deben conservar un asiento en ese autobús.");}ContentValues value=new ContentValues();value.put("registration_closed",1);value.put("finalized",1);db.getWritableDatabase().update("transport_trips",value,"id=?",new String[]{String.valueOf(trip.id)});trip.registrationClosed=true;trip.finalized=true;}
    void reopenProgram(Trip trip){ContentValues value=new ContentValues();value.put("finalized",0);db.getWritableDatabase().update("transport_trips",value,"id=?",new String[]{String.valueOf(trip.id)});trip.finalized=false;}
    List<PersonChoice> historicalPeople(){List<PersonChoice> result=new ArrayList<>();try(Cursor r=db.getReadableDatabase().rawQuery("SELECT source_kind,source_id,MAX(passenger_name) FROM transport_passengers GROUP BY source_kind,source_id ORDER BY MAX(passenger_name) COLLATE NOCASE",null)){while(r.moveToNext())result.add(new PersonChoice(r.getString(0),r.getLong(1),r.getString(2)));}return result;}
    List<PassengerTrip> tripsFor(String kind,long sourceId){List<PassengerTrip> result=new ArrayList<>();String sql="SELECT t.travel_date,t.departure_time,t.reason,t.departure_place,COALESCE(b.bus_number,0),COALESCE(s.seat_number,0),CASE WHEN b.captain_passenger_id=p.id THEN 1 ELSE 0 END,CASE WHEN b.assistant_passenger_id=p.id THEN 1 ELSE 0 END FROM transport_passengers p JOIN transport_trips t ON t.id=p.trip_id LEFT JOIN transport_seats s ON s.passenger_id=p.id LEFT JOIN transport_buses b ON b.id=s.bus_id WHERE p.source_kind=? AND p.source_id=? ORDER BY t.travel_date DESC,t.departure_time DESC";try(Cursor r=db.getReadableDatabase().rawQuery(sql,new String[]{kind,String.valueOf(sourceId)})){while(r.moveToNext()){PassengerTrip item=new PassengerTrip();item.date=r.getString(0);item.time=r.getString(1);item.reason=r.getString(2);item.departurePlace=r.getString(3);item.bus=r.getInt(4);item.seat=r.getInt(5);item.captain=r.getInt(6)!=0;item.assistant=r.getInt(7)!=0;result.add(item);}}return result;}
    String passengerName(long id){return id==0?"PENDIENTE":passenger(id).name;}
    static String humanDate(String iso){LocalDate date=LocalDate.parse(iso);return String.format(Locale.ROOT,"%02d/%02d/%04d",date.getDayOfMonth(),date.getMonthValue(),date.getYear());}
}
